// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter, Initializable} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }
    function testFuzz_property(address admin) public {
        // A freshly deployed C has initializers disabled by its constructor, so EVERY call to
        // initialize must revert with the exact custom error Initializable.InvalidInitialization.
        // The mutant (initializer modifier removed) instead reverts with NotInitializing raised by
        // the inner onlyInitializing guard, so the revert payload selector differs for any admin.
        (bool ok, bytes memory ret) = address(c).call(abi.encodeCall(c.initialize, (admin)));
        assertTrue(
            !ok && ret.length == 4
                && bytes4(ret) == Initializable.InvalidInitialization.selector
        );
    }
}
